function mean(a){return a.length?a.reduce((s,[,v])=>s+v,0)/a.length:null}function sum(a){return a.length?a.reduce((s,[,v])=>s+v,0):null}
async function loadData(){pauseHistory();powerCache=null;renderDailyWind();const id=++state.request;if(controller)controller.abort();controller=new AbortController();const localController=controller;const timer=setTimeout(()=>localController.abort(),45000);const lat=state.selectedLat,lon=state.selectedLon,name=state.name;state.data=null;renderAction();['temp','moisture','rain','frost','maxTemp','airHumidity','wind','hotDays'].forEach(x=>$(x).textContent='—');$('chart').innerHTML='<p>Consultando la serie diaria…</p>';$('coverage').textContent='';$('status').textContent='Consultando NASA POWER…';$('refresh').disabled=true;$('raw').hidden=true;scenario();const days=Number($('period').value),end=ago(7),start=ago(7+days+28);const url='https://power.larc.nasa.gov/api/temporal/daily/point?'+new URLSearchParams({parameters:'T2M,T2M_MIN,T2M_MAX,PRECTOTCORR,GWETROOT,RH2M,WS2M',community:'AG',latitude:lat.toFixed(4),longitude:lon.toFixed(4),start:stamp(start),end:stamp(end),format:'JSON','time-standard':'UTC'});state.url=url;$('raw').href=url;
try{const response=await fetch(url,{signal:localController.signal});if(!response.ok)throw Error('NASA respondió HTTP '+response.status);const data=await response.json();if(id!==state.request)return;const p=data.properties?.parameter;if(!p)throw Error('Respuesta sin parámetros disponibles');powerCache={p,lat,lon,name,url,queried:new Date().toISOString(),latest:iso(end),days};applyHistory();}catch(e){if(id!==state.request)return;$('status').textContent='No se pudo consultar NASA. '+(e.name==='AbortError'?'Tiempo de espera agotado.':e.message)+'. Reintentá con Actualizar.';$('chart').innerHTML='<p>Sin datos. No se muestran valores inventados.</p>';$('raw').hidden=false;}finally{clearTimeout(timer);if(id===state.request)$('refresh').disabled=false}}

function showPowerWindow(p,lat,lon,name,url,days,start,end){const filtered={};for(const [key,values] of Object.entries(p))filtered[key]=Object.fromEntries(Object.entries(values).filter(([day])=>day>=stamp(start)&&day<=stamp(end)));p=filtered;const t=validEntries(p.T2M),m=validEntries(p.GWETROOT),r=validEntries(p.PRECTOTCORR),f=validEntries(p.T2M_MIN),mx=validEntries(p.T2M_MAX),rh=validEntries(p.RH2M),wind=validEntries(p.WS2M);state.data={name,lat,lon,start:iso(start),end:iso(end),days,maxTemp:mx.length?Math.max(...mx.map(x=>x[1])):null,hotDays:mx.length?mx.filter(x=>x[1]>=35).length:null,airHumidity:mean(rh),wind:mean(wind),temp:mean(t),moisture:mean(m),rain:sum(r),frost:f.length?f.filter(([,v])=>v<=0).length:null,counts:{temp:t.length,moisture:m.length,rain:r.length,frost:f.length,maxTemp:mx.length,airHumidity:rh.length,wind:wind.length},rainSeries:r,url,queried:powerCache.queried};$('temp').textContent=num(state.data.temp)+'°';$('moisture').textContent=num(state.data.moisture,2);$('rain').textContent=num(state.data.rain);$('frost').textContent=num(state.data.frost,0);$('maxTemp').textContent=num(state.data.maxTemp)+' °C';$('airHumidity').textContent=num(state.data.airHumidity)+' %';$('wind').textContent=num(state.data.wind)+' m/s';$('hotDays').textContent=num(state.data.hotDays,0);const any=[t,m,r,f].some(a=>a.length);$('status').textContent=(any?(historyMode?'Historia real':'Datos recientes'):'Sin observaciones válidas')+' · '+iso(start)+' al '+iso(end)+' · consulta '+new Date(powerCache.queried).toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Argentina/Jujuy'});$('coverage').textContent=`Cobertura: temperatura ${t.length}/${days}; humedad ${m.length}/${days}; lluvia ${r.length}/${days}; mínima ${f.length}/${days}; máxima ${mx.length}/${days}; humedad del aire ${rh.length}/${days}; viento ${wind.length}/${days}. No se rellenan días faltantes. Acumulado parcial si faltan registros.`;$('raw').hidden=false;drawChart(r);scenario();renderAction();renderDailyWind()}
function drawChart(series){if(!series.length){$('chart').innerHTML='<p>Sin precipitación válida para este período.</p>';return}const W=680,H=110,max=Math.max(1,...series.map(x=>x[1])),bw=(W-55)/(state.data?.days||series.length);const origin=Date.parse((state.data?.start||iso(new Date()))+'T00:00:00Z');let svg=`<svg viewBox="0 0 ${W} 145" role="img" aria-label="Precipitación diaria NASA, en milímetros">`;for(let i=0;i<3;i++){const y=10+i*H/2;svg+=`<line x1="36" y1="${y}" x2="678" y2="${y}" stroke="#e6eadd"/><text x="0" y="${y+4}" font-size="9" fill="#87927c">${num(max*(1-i/2),0)}</text>`}series.forEach(([date,v])=>{const i=(Date.parse(date.slice(0,4)+'-'+date.slice(4,6)+'-'+date.slice(6,8)+'T00:00:00Z')-origin)/86400000;const h=v/max*H;svg+=`<rect x="${40+i*bw}" y="${120-h}" width="${Math.max(.7,bw*.65)}" height="${h}" rx="1" fill="#91a773"><title>${date}: ${v} mm</title></rect>`});svg+=`<text x="40" y="140" font-size="9" fill="#87927c">${series[0][0]}</text><text x="670" y="140" text-anchor="end" font-size="9" fill="#87927c">${series.at(-1)[0]}</text></svg>`;$('chart').innerHTML=svg}
const escapeHTML=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rotations(){window.rotationAdvisor?.render()}
function scenario(){const change=Number($('rainScenario').value);$('rainOutput').textContent=(change>0?'+':'')+change+' %';$('scenarioResult').textContent=state.data?.rain!=null?num(state.data.rain*(1+change/100))+' mm · escenario':'Sin lluvia disponible'}
['priority','water','market','currentCrop'].forEach(id=>$(id).addEventListener('input',rotations));$('rainScenario').oninput=scenario;$('period').onchange=loadData;$('refresh').onclick=loadData;
$('export').onclick=()=>{const report={comparadorRotaciones:window.terraRotationReport||null,observacionesDeCampo:observations,capaMapa:currentLayer().name,fechaCapa:imageDate(currentLayer(),$('mapDate').value),guiaCampo:$('actionDetail').innerText,proyecto:'TerraJujuy',tipo:'Exploración educativa, no prescripción agronómica',datosNASA:state.data||'Sin datos disponibles',rotacionActual:$('currentCrop').value,prioridad:$('priority').selectedOptions[0].textContent,agua:$('water').selectedOptions[0].textContent,mercado:$('market').selectedOptions[0].textContent,escenarioHipoteticoLluviaPorcentaje:Number($('rainScenario').value),comparacion:$('rotationCards').innerText,limites:'Valores regionales; no diagnóstico de fertilidad, pronóstico ni cálculo de rentabilidad. Validación local necesaria.'};const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='TerraJujuy-informe.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
