let observations=[];let selectedProblem='water';
try{const saved=JSON.parse(localStorage.getItem('terrajujuy-observations-v2')||'[]');if(Array.isArray(saved))observations=saved.filter(n=>n&&typeof n.id==='string'&&typeof n.plant==='string'&&typeof n.note==='string'&&typeof n.date==='string'&&typeof n.identification==='string'&&Number.isFinite(n.lat)&&Number.isFinite(n.lon)&&Math.abs(n.lat)<=90&&Math.abs(n.lon)<=180).slice(0,300)}catch(e){observations=[]}
const problems={
water:{title:'Falta de agua: anticipar pérdidas',icon:'💧',impact:'Una reserva insuficiente puede limitar el crecimiento y aumentar el costo de producción. Una lluvia aislada no demuestra recuperación del agua en el perfil.',layer:'soil',evidence:d=>d?`Índice de humedad radicular POWER: ${num(d.moisture,2)}. Lluvia acumulada: ${num(d.rain)} mm en ${d.counts.rain}/${d.days} días válidos. No es un diagnóstico oficial de sequía.`:'Consultá un punto para incorporar su humedad radicular y precipitación.',need:'Textura y profundidad del suelo, humedad a distintas profundidades, capacidad de campo, punto de marchitez, raíces, etapa del cultivo, agua y caudal disponibles.',steps:['Medir el agua disponible en el lote y contrastar con registros recientes de lluvia y riego.','Evaluar conservación de residuos y cobertura; si la cobertura está viva, considerar también su consumo de agua.','Revisar fugas y uniformidad del sistema de riego. Priorizar decisiones con la etapa del cultivo y disponibilidad real.','Usar la calculadora solo después de determinar una lámina neta con medición y asesoramiento.'],verify:'Volver a medir humedad a profundidad de raíces y registrar el volumen efectivamente aplicado.'},
heat:{title:'Calor y frío: importa la etapa del cultivo',icon:'☀',impact:'Las temperaturas extremas pueden alterar crecimiento y reproducción. El impacto depende de especie, variedad, duración del evento y disponibilidad de agua.',layer:'heat',evidence:d=>d?`Tmax máxima del período: ${num(d.maxTemp)} °C; ${num(d.hotDays,0)} días con Tmax ≥ 35 °C y ${num(d.frost,0)} días con Tmin ≤ 0 °C. Indicadores históricos regionales, no pronóstico.`:'Esperando temperaturas regionales del punto seleccionado.',need:'Temperatura medida en el cultivo, etapa fenológica, variedad, duración del evento, disponibilidad de agua y pronóstico local validado.',steps:['Contrastar el panel regional con termómetros del lote, especialmente en bajos y laderas.','Revisar si la fase más sensible del cultivo coincide con eventos históricos; ajustar próximos calendarios con asesoramiento.','Evaluar protecciones físicas apropiadas al cultivo y a la escala; verificar costo y factibilidad antes de instalarlas.','No activar riego antiheladas ni tratamientos solo con este panel: requieren diseño, condiciones y seguimiento específicos.'],verify:'Registrar temperaturas y síntomas antes y después del evento. Evaluar daño con una visita de campo.'},
erosion:{title:'Conservar el suelo que sostiene la cosecha',icon:'⛰',impact:'La escorrentía y el viento pueden remover suelo superficial y nutrientes. La altura por sí sola no determina el riesgo: también influyen pendiente, cobertura y suelo.',layer:'elevation',evidence:()=> 'El mapa SRTM muestra elevación. No se calculó pendiente, erosión anual ni estabilidad del terreno.',need:'Pendiente y longitud de ladera medidas, textura, infiltración, cobertura del suelo, lluvias intensas y señales de surcos o cárcavas.',steps:['Recorrer las rutas de escurrimiento después de lluvias cuando sea seguro y registrar zonas con suelo expuesto.','Evaluar mantener residuos y reducir perturbaciones del suelo según el sistema productivo.','Estudiar franjas de protección, coberturas y manejo en curvas de nivel con un técnico.','No ejecutar terrazas, desvíos o drenajes sin diseño local: pueden concentrar agua y desplazar el daño.'],verify:'Comparar fotografías desde el mismo punto y controlar aparición de surcos y acumulación de sedimentos.'},
forest:{title:'Investigar pérdida de vegetación',icon:'🌳',impact:'La pérdida de cobertura puede dejar superficies más expuestas y cambiar el movimiento del agua. Para el productor importa distinguir una cosecha normal de degradación o pérdida de bosque.',layer:'disturbance',evidence:()=> 'OPERA/HLS muestra categorías de alteración. La capa no determina la causa, no calcula hectáreas y no confirma deforestación.',need:'Cobertura previa, fecha de cosecha, historial de incendios y manejo, imágenes comparables y observación en campo.',steps:['Activar “Pérdida de vegetación” y contrastar la señal con “Uso del suelo” y el historial de la parcela.','Comparar fechas y registrar si hubo cosecha, fuego u otra intervención conocida.','Visitar las zonas señaladas y documentar suelo, cobertura y regeneración; no atribuir la causa por el color del mapa.','Si se confirma degradación, evaluar protección del suelo y restauración con especies nativas adecuadas junto con profesionales locales.'],verify:'Volver a observar en la misma época del año. Separar recuperación estacional de restauración sostenida.'},
parasites:{title:'Plantas parásitas: identificar antes de controlar',icon:'🌿',impact:'Las plantas parásitas pueden afectar al hospedante. Síntomas como amarillamiento o menor crecimiento también tienen otras causas: no son prueba de parasitismo.',layer:'vegetation',evidence:()=> 'Esta web no detecta plantas parásitas desde el satélite. El catálogo aporta nombres de referencia y el cuaderno ubica observaciones ingresadas por el productor.',need:'Identificación botánica, cultivo hospedante, fotos de planta y unión con el hospedante, distribución del foco, historial de semillas y maquinaria.',steps:['Registrar el punto, nombre tentativo, fecha, cultivo hospedante y síntomas en el cuaderno.','Solicitar identificación local; distinguir planta parásita de maleza, enredadera u otra causa de estrés.','Evitar trasladar material sospechoso entre parcelas mientras se define el diagnóstico; acordar medidas de higiene y manejo con el técnico.','Elegir control y rotación solo con la especie confirmada y las recomendaciones locales. No se prescriben herbicidas ni dosis en esta herramienta.'],verify:'Delimitar el foco y realizar visitas comparables. Un cambio del NDVI no demuestra eliminación del parásito.'},
soil:{title:'Suelo y nutrientes: medir para decidir',icon:'◉',impact:'Un suelo con restricciones químicas o físicas puede limitar el cultivo aun cuando haya agua. No se puede medir fertilidad usando únicamente color, verdor o humedad satelital.',layer:'cover',evidence:()=> 'pH, nutrientes, salinidad, materia orgánica y compactación: sin medición disponible. El panel no asigna un puntaje ficticio de salud del suelo.',need:'Análisis representativo de suelo, profundidad y fecha de muestreo, textura, materia orgánica, pH, salinidad y extracción del cultivo.',steps:['Planificar un muestreo representativo con profundidad y zonas de manejo definidas.','Interpretar el análisis según cultivo, rendimiento objetivo razonable y antecedentes del lote.','Evaluar rotaciones, residuos y coberturas para mejorar el sistema en el tiempo, considerando agua y costos.','Definir fertilización y enmiendas con análisis e interpretación técnica. No aplicar dosis deducidas de un mapa de vegetación.'],verify:'Repetir muestreos comparables y registrar respuesta del cultivo y evolución de los indicadores.'},
flood:{title:'Exceso de agua y anegamiento',icon:'☂',impact:'La saturación prolongada puede limitar el oxígeno de las raíces, retrasar labores y favorecer pérdidas de nutrientes. Un acumulado de lluvia no demuestra por sí solo anegamiento.',layer:'rain',evidence:d=>d?`Precipitación POWER: ${num(d.rain)} mm; cobertura ${d.counts.rain}/${d.days} días. GPM aporta una imagen regional de tasa de lluvia, no profundidad de agua en el lote.`:'Consultá precipitación y comprobá físicamente si hay agua acumulada.',need:'Duración del anegamiento, infiltración, nivel freático, estado de drenajes, profundidad de raíces y tránsito de maquinaria.',steps:['Registrar bajos, duración del agua visible y drenajes obstruidos sin ingresar a zonas inseguras.','Evitar labores que agraven compactación cuando el suelo no soporta tránsito.','Revisar drenaje y manejo de escorrentía con diseño técnico; no desviar agua a otros predios.','Reevaluar siembra, nutrición y sanidad tras el evento con observación del cultivo.'],verify:'Controlar tiempo de recuperación del suelo y desarrollo de raíces; conservar un registro de lluvias y labores.'}
};
function renderAction(){if(!$('actionDetail'))return;const p=problems[selectedProblem];$('actionDetail').innerHTML=`<div class="action-title"><span>${p.icon}</span><div><span class="eyebrow">PLAN DE OBSERVACIÓN Y MANEJO</span><h3>${p.title}</h3></div></div><p>${p.impact}</p><div class="evidence-box"><b>Lo que sabemos en ${escapeHTML(state.name)}</b><p>${p.evidence(state.data)}</p></div><div class="action-columns"><div><h4>Qué datos faltan</h4><p>${p.need}</p><button id="showProblemLayer" class="secondary-button">Ver capa relacionada ↗</button></div><div><h4>Pasos para evaluar</h4><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div></div><p class="followup"><b>Cómo verificar:</b> ${p.verify}</p><small>Propuesta preventiva para revisar localmente. No reemplaza diagnóstico, diseño de riego ni prescripción agronómica.</small>`;$('showProblemLayer').onclick=()=>{document.querySelector(`[data-layer="${p.layer}"]`).click();showSection('monitor')}}
const plantHealth={"Caña de azúcar": {"symptoms": "Brotes muy finos, hojas estrechas o una estructura negra en forma de látigo pueden ser compatibles con carbón. Bandas pálidas también pueden tener causas ambientales.", "parts": "Brotes, punta del tallo y láminas foliares.", "timing": "Desde el rebrote y durante el crecimiento; anotar fecha de corte, primer brote anormal y evolución.", "pattern": "Marcar cepas afectadas y comparar dentro del mismo surco y entre surcos. No trasladar material sospechoso para propagación.", "source": "https://plantdiseasehandbook.tamu.edu/industry-specialty/sugar-crops/sugarcane/"}, "Tabaco": {"symptoms": "Mosaico de verde claro y oscuro, deformación de hojas y menor crecimiento son compatibles con virosis, incluido TMV; no bastan para confirmarla.", "parts": "Hojas jóvenes y adultas; observar también porte de la planta.", "timing": "Revisar en almácigo, trasplante y crecimiento. Registrar labores previas al primer síntoma.", "pattern": "Comparar plantas aisladas y secuencias de plantas manipuladas. La distribución por sí sola no confirma transmisión.", "source": "https://content.ces.ncsu.edu/control-of-tobacco-mosaic-virus-on-flue-cured-tobacco"}, "Papa": {"symptoms": "Manchas irregulares de aspecto húmedo, verde oscuro a pardo, pueden corresponder a tizón tardío. También hay otras causas de manchas o marchitez.", "parts": "Hojas, pecíolos y tallos; revisar tubérculos con asesoramiento.", "timing": "Durante el desarrollo del follaje, especialmente tras períodos frescos y húmedos. Registrar lluvia y primera observación.", "pattern": "Delimitar focos y comprobar si se expanden; fotografiar plantas vecinas sin síntomas.", "source": "https://ipm.ucanr.edu/home-and-landscape/late-blight/"}, "Quinua": {"symptoms": "Áreas más claras en hojas, curvatura de la lámina y menor crecimiento pueden aparecer con mildiu; el color varía con el material vegetal.", "parts": "Haz y envés de hojas, desde la base hasta el ápice.", "timing": "Desde crecimiento vegetativo hasta desarrollo de panoja; anotar etapa y humedad del follaje.", "pattern": "Comparar variedades y sectores del lote; registrar plantas aisladas o manchones sin dar por confirmada la causa.", "source": "https://pnwhandbooks.org/plantdisease/host-disease/quinoa-chenopodium-quinoa-downy-mildew"}, "Maíz": {"symptoms": "Pústulas elevadas y polvorientas en ambas caras de la hoja pueden ser compatibles con roya común. El enrollamiento foliar tiene otras causas, incluido estrés hídrico.", "parts": "Ambas caras de hojas y otras partes aéreas; observar espigas y tallos por separado.", "timing": "Desde crecimiento hasta llenado; registrar si las lesiones aparecen antes o después de floración.", "pattern": "Recorrer bordes e interior, y comparar hojas bajas y altas. Anotar porcentaje observado sin extrapolar todo el lote.", "source": "https://ipm.ucanr.edu/agriculture/corn/common-rust/"}, "Poroto": {"symptoms": "Pústulas secas de tonos rojizos, amarillos o anaranjados, especialmente en el envés, pueden indicar roya.", "parts": "Envés y haz de hojas; inspeccionar vainas y cuello por separado.", "timing": "Durante crecimiento, floración y formación de vainas; registrar fecha y avance entre visitas.", "pattern": "Marcar focos y plantas testigo próximas. Evitar atribuir cualquier amarillamiento a roya.", "source": "https://ipm.ucanr.edu/home-and-landscape/bean-rust/"}, "Soja": {"symptoms": "Fallas de emergencia, marchitez o lesiones pardas en raíz y base del tallo pueden asociarse a enfermedades de plántulas. Varias causas se parecen.", "parts": "Raíz, cuello, base del tallo y cotiledones.", "timing": "Especial atención desde siembra a establecimiento; anotar lluvias, compactación y drenaje.", "pattern": "Comparar bajos y zonas bien drenadas, manchones y plantas aisladas. Conservar historial de la semilla.", "source": "https://apps.extension.umn.edu/agriculture/crop-diseases/soybean/soybeandisease.html"}, "Trigo": {"symptoms": "Pústulas rojizas o anaranjadas dispersas o agrupadas sobre hojas pueden corresponder a roya foliar.", "parts": "Haz foliar, vainas y tallos; diferenciar lesiones en cada órgano.", "timing": "Desde macollaje a llenado; registrar momento respecto de espigazón.", "pattern": "Comparar franjas, bordes y centro; registrar si aumenta entre visitas.", "source": "https://ipm.ucanr.edu/agriculture/small-grains/leaf-rusts-of-wheat-and-barley-crown-rust-of-oats/"}, "Avena": {"symptoms": "Pústulas oblongas y anaranjadas en hojas pueden ser compatibles con roya de la corona. No toda decoloración es roya.", "parts": "Hojas, vainas y tallos; anotar si existe material polvoriento.", "timing": "Durante crecimiento y antes de corte o terminación de cobertura.", "pattern": "Delimitar sectores afectados y contrastar plantas de igual edad y variedad.", "source": "https://ipm.ucanr.edu/agriculture/small-grains/leaf-rusts-of-wheat-and-barley-crown-rust-of-oats/"}, "Vicia": {"symptoms": "Observar amarillamiento, pérdida de vigor, marchitez, lesiones y daño por alimentación; son señales inespecíficas que requieren examinar raíz y follaje.", "parts": "Folíolos, tallos, cuello y raíces; nodulación visible con revisión técnica.", "timing": "Desde implantación hasta floración y antes de terminar la cobertura.", "pattern": "Comparar bajos, bordes y zonas compactadas; distinguir distribución del síntoma de distribución de la especie.", "source": "https://content.ces.ncsu.edu/extension-gardener-handbook/7-diagnostics"}, "Cuscuta": {"symptoms": "Tallos filiformes amarillos o anaranjados enrollados al hospedante; el hospedante puede perder vigor. Buscar conexiones, no solo una enredadera cercana.", "parts": "Tallos y conexiones con el hospedante; flores y cápsulas de la parásita.", "timing": "Registrar primera aparición y si ya hay flores o semillas. No asumir un mes fijo para todas las especies.", "pattern": "Marcar borde y extensión del foco, plantas conectadas y material que pudo transportar semillas.", "source": "https://ipm.ucanr.edu/home-and-landscape/dodder/"}, "Jopo": {"symptoms": "Emergencia de tallos florales desde el suelo junto al hospedante; este puede mostrar menor vigor antes de que la parásita sea visible.", "parts": "Conexión a raíces y tallos florales emergentes; identificación por especialista.", "timing": "Registrar fecha de emergencia y floración. La etapa subterránea puede pasar inadvertida.", "pattern": "Delimitar focos e identificar hospedantes; no inferir presencia en toda la región ni en Jujuy.", "source": "https://broomrape.ucdavis.edu/frequently-asked-questions"}, "Striga": {"symptoms": "El hospedante puede mostrar crecimiento reducido y estrés; esos síntomas no prueban parasitismo. La identificación requiere examinar la planta parásita.", "parts": "Raíces del hospedante y tallos, hojas y flores de la parásita.", "timing": "Registrar aparición y floración; parte de la interacción ocurre antes de emerger.", "pattern": "Referencia internacional: no es un registro de presencia en Argentina. Solicitar verificación local antes de atribuir un foco.", "source": "https://www.apsnet.org/edcenter/Pages/ParasiticPlants.aspx"}, "Girasol": {"symptoms": "Registrar manchas, amarillamiento, marchitez y deformaciones; distinguir la maduración normal del capítulo de un deterioro temprano.", "parts": "Hojas de distintas edades, tallo, cuello y capítulo.", "timing": "Comparar crecimiento, floración y llenado de semillas; anotar momento de aparición respecto de cada etapa.", "pattern": "Contrastar bordes, bajos y plantas vecinas; verificar si afecta solo al girasol o a varias especies.", "source": "https://content.ces.ncsu.edu/extension-gardener-handbook/7-diagnostics"}, "Tomate": {"symptoms": "Manchas pardas u oscuras en hojas, tallos y frutos pueden ser compatibles con tizón temprano; lesiones bacterianas pueden parecerse.", "parts": "Hojas bajas y altas, tallos y superficie de frutos.", "timing": "Revisar durante crecimiento y fructificación, especialmente tras períodos húmedos. Registrar primera fecha y expansión.", "pattern": "Fotografiar focos y plantas sanas próximas; describir si empezó abajo o arriba en la planta.", "source": "https://ipm.ucanr.edu/agriculture/tomato/early-blight/"}, "Pimiento": {"symptoms": "Pequeñas lesiones de aspecto húmedo que se oscurecen, a veces con halo, pueden asociarse a mancha bacteriana; no confirma el agente.", "parts": "Hojas, tallos jóvenes y frutos; separar daño solar de manchas en tejido.", "timing": "Desde trasplante hasta cosecha; registrar lluvia, riego y labores anteriores al síntoma.", "pattern": "Comparar plantas del mismo almácigo y sectores del lote, sin deducir el origen solo por su ubicación.", "source": "https://extension.illinois.edu/plant-problems/bacterial-diseases-solanaceous-crops"}, "Zapallo / zucchini": {"symptoms": "Crecimiento blanquecino y polvoriento en hojas puede ser compatible con oídio; diferenciarlo de manchas naturales de algunas variedades.", "parts": "Ambas caras de hojas y pecíolos; observar senescencia y frutos.", "timing": "Durante desarrollo de la cubierta foliar y fructificación; registrar etapa y avance.", "pattern": "Comparar hojas de igual edad y sectores con distinta ventilación.", "source": "https://ipm.ucanr.edu/home-and-landscape/powdery-mildew-on-cucurbits/"}, "Cebolla": {"symptoms": "Hojas que se aclaran, amarillean y colapsan, a veces con crecimiento grisáceo o violáceo, pueden ser compatibles con mildiu.", "parts": "Hojas tubulares, tallos florales y bulbos si corresponde.", "timing": "Durante desarrollo foliar y formación del bulbo; registrar períodos de hojas húmedas.", "pattern": "Pueden observarse manchones de plantas amarillas: delimitar y seguir su evolución.", "source": "https://ipm.ucanr.edu/agriculture/onion-and-garlic/downy-mildew/"}, "Zanahoria": {"symptoms": "Crecimiento blanco y polvoriento sobre hojas adultas o pecíolos puede ser compatible con oídio. Las raíces deformadas requieren otra evaluación.", "parts": "Hojas adultas, pecíolos y raíz cosechada por separado.", "timing": "Revisar follaje maduro y documentar estado de raíces durante muestreos y cosecha.", "pattern": "Comparar manchones con plantas sanas del mismo estado; anotar humedad y densidad.", "source": "https://ipm.ucanr.edu/agriculture/carrot/powdery-mildew/"}, "Lechuga": {"symptoms": "Crecimiento gris-blanco polvoriento en ambas caras de hojas puede asociarse a oídio; no confundir con residuos de aplicaciones.", "parts": "Haz, envés y hojas exteriores del cogollo.", "timing": "Especial atención en plantas maduras; registrar si hubo aplicaciones y la fecha del primer síntoma.", "pattern": "Contrastar plantas y sectores; fotografiar antes de manipular la hoja.", "source": "https://ipm.ucanr.edu/agriculture/lettuce/powdery-mildew/"}, "Centeno": {"symptoms": "Registrar manchas, pústulas, amarillamiento, vuelco y pérdida de cobertura; describir cada señal sin asignar automáticamente una enfermedad.", "parts": "Hojas, vainas, tallos, raíces y espiga cuando exista.", "timing": "Desde macollaje hasta espigazón o terminación de cobertura.", "pattern": "Comparar surcos, bajos y bordes, y distinguir daño mecánico o de labores.", "source": "https://content.ces.ncsu.edu/extension-gardener-handbook/7-diagnostics"}, "Trébol blanco": {"symptoms": "Tallos finos de cuscuta que rodean y penetran tallos del trébol pueden reducir el vigor. Amarillamiento aislado no demuestra parasitismo.", "parts": "Estolones, tallos, hojas y unión con la parásita.", "timing": "Durante establecimiento y crecimiento; registrar si la parásita florece.", "pattern": "Delimitar plantas conectadas y borde del foco; documentar sin trasladar material sospechoso.", "source": "https://pnwhandbooks.org/plantdisease/host-disease/clover-trifolium-spp-dodder"}, "Sorgo": {"symptoms": "Observar manchas, perforaciones, marchitez y menor desarrollo; separar señales foliares de daños en panoja o tallo. No permiten un diagnóstico único.", "parts": "Hojas de distintas edades, tallo, cuello y panoja.", "timing": "Desde establecimiento hasta floración, llenado o corte forrajero.", "pattern": "Anotar si coincide con franjas de manejo, bajos o bordes; comparar plantas de igual etapa.", "source": "https://content.ces.ncsu.edu/extension-gardener-handbook/7-diagnostics"}};
const regionalPlants=[{"plant": {"name": "Liga · muérdago criollo", "latin": "Ligaria cuneifolia", "type": "parasite", "family": "Loranthaceae", "icon": "🌿", "cycle": "Perenne", "source": "https://mendoza.conicet.gov.ar/wp-content/uploads/sites/225/2025/03/Ligaria-cuneifolia_Ficha-alumnos.pdf", "role": "Hemiparásita nativa de ramas", "recognize": "Arbusto de copa redondeada, hojas carnosas con forma de espátula y flores rojas o amarillentas. Crece unido a ramas de otra planta.", "learn": "Fotosintetiza, pero toma agua y nutrientes del hospedante. Sus frutos también son alimento para aves. No confundir parasitismo con ausencia de valor ecológico.", "distribution": "CONICET informa su presencia en Argentina desde Jujuy hasta La Pampa. SIB documenta registros en los parques El Rey y Los Cardones, en Salta. Esto no confirma presencia en el punto del mapa.", "watch": "Identificar hospedante y carga de plantas, registrar fotos y revisar el vigor con un técnico. No se indica cortar ramas ni aplicar productos por una imagen satelital.", "text": "Puede observarse sobre molles, algarrobos, chañares y jarillas. Registrar la unión al hospedante; un nombre común como “liga” no distingue todas las especies.", "photo": {"image": "assets/Ligaria_cuneifolia.jpg", "credit": "Especies-mendoza-23", "license": "CC BY-SA 4.0", "source": "https://commons.wikimedia.org/wiki/File:Ligaria.cuneifolia.jpg", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "species": "Ligaria cuneifolia", "caption": "Planta viva con flores. Fotografía de Mendoza, Argentina; no indica presencia en el punto seleccionado."}}, "health": {"symptoms": "Buscar la planta unida a la rama. Anotar pérdida de vigor o ramas secas del hospedante sin atribuir automáticamente esos cambios a la liga.", "parts": "Ramas, punto de unión, hojas y flores de la hemiparásita; copa del hospedante.", "timing": "Comparar el mismo árbol entre visitas; fechar floración, frutos y primera señal de deterioro. No se fija un calendario universal.", "pattern": "Registrar árboles aislados o grupos y cuántas ramas tienen plantas adheridas. Separar distribución de la especie de distribución del daño.", "source": "https://mendoza.conicet.gov.ar/wp-content/uploads/sites/225/2025/03/Ligaria-cuneifolia_Ficha-alumnos.pdf"}}, {"plant": {"name": "Cardón · pasacana", "latin": "Trichocereus atacamensis", "type": "native", "family": "Cactaceae", "icon": "🌵", "cycle": "Perenne", "source": "https://sib.gob.ar/especies/trichocereus-atacamensis", "role": "Cactus nativo · conservación", "recognize": "Cactus de tallos columnares con costillas y espinas, a veces ramificado. La foto muestra Echinopsis atacamensis subsp. pasacana; el SIB reúne ese nombre entre los sinónimos de Trichocereus atacamensis.", "learn": "Es flora nativa del paisaje, no una cobertura agrícola ni un cultivo propuesto para rotación. Conocerla ayuda a reconocer la biodiversidad alrededor de las parcelas.", "distribution": "Referencia del noroeste argentino. Presencia validada por SIB en el Parque Nacional Los Cardones, Salta. “Cardón” se usa para varias especies: esta ficha identifica una de ellas.", "text": "APN describe los cardonales como un componente emblemático del Monte y los valles calchaquíes. No extrapolar su presencia a cualquier altitud o localidad de Jujuy.", "watch": "Observar sin extraer ejemplares ni dañar tallos. Para viveros o restauración, consultar procedencia legal, identificación y orientación local.", "photo": {"image": "assets/Cardon.jpg", "credit": "Mourial", "license": "CC BY 3.0", "source": "https://commons.wikimedia.org/wiki/File:Cardon.JPG", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "species": "Echinopsis atacamensis subsp. pasacana", "caption": "Cardones en Argentina. Nombre de referencia de la ficha: Trichocereus atacamensis; Echinopsis atacamensis es un sinónimo utilizado por la fuente fotográfica."}}, "health": {"symptoms": "Registrar heridas, tejidos oscurecidos, pérdida de firmeza o roturas. Son señales de observación, no un diagnóstico de hongos o plagas.", "parts": "Base, tallos, costillas y ramas; fotografiar desde una distancia segura.", "timing": "Repetir fotografías del mismo ejemplar y anotar eventos de lluvia, helada o daño mecánico entre visitas.", "pattern": "Comparar ejemplares próximos y su ubicación en el terreno, sin tocar ni transportar tejido.", "source": "https://sib.gob.ar/especies/trichocereus-atacamensis"}}, {"plant": {"name": "Yerba del pajarito · corpo", "latin": "Tripodanthus acutifolius", "type": "parasite", "family": "Loranthaceae", "icon": "🌿", "cycle": "Perenne", "source": "https://ecologia.misiones.gob.ar/yerba-del-pajarito-una-planta-habitual-de-misiones-que-no-necesariamente-representa-una-plaga-para-los-arboles/", "role": "Hemiparásita nativa de árboles", "recognize": "Crece sobre ramas y copas; tiene hojas verdes, flores blancas o crema perfumadas y frutos pegajosos dispersados por aves.", "learn": "El Ministerio de Ecología de Misiones señala que una presencia equilibrada no necesariamente compromete la supervivencia del árbol. La evaluación debe considerar hospedante y abundancia.", "distribution": "Documentada por el Ministerio de Ecología en toda la provincia de Misiones, noreste argentino. No se presenta como registro confirmado en Jujuy.", "text": "La fotografía de herbario permite observar material botánico conservado. No muestra una infestación actual ni síntomas del hospedante.", "watch": "Identificar antes de intervenir. Registrar cantidad de plantas y estado de la copa; evaluar manejo con especialistas y conservar la fauna asociada.", "photo": {"image": "assets/Tripodanthus_acutifolius.jpg", "credit": "Uruguayan Barcode of Life Initiative (BoL-UY)", "license": "CC BY 4.0", "source": "https://commons.wikimedia.org/wiki/File:Tripodanthus_acutifolius-CA102MVFA-FAGRO-UDELAR.jpg", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "species": "Tripodanthus acutifolius", "caption": "Ejemplar seco de herbario CA102MVFA, colectado en Rivera, Uruguay (2022). Los colores del material seco no representan síntomas de una planta viva.", "herbarium": true}}, "health": {"symptoms": "Reconocer ramas ocupadas por la hemiparásita. Si hay decaimiento del árbol, registrar también sequía, heridas y otros factores; la presencia sola no prueba daño.", "parts": "Copa, ramas hospedantes, unión de ambas plantas, hojas, flores y frutos.", "timing": "Fechar cada visita y registrar etapa reproductiva; las fechas dependen del ambiente y no se deducen del mapa.", "pattern": "Registrar árboles afectados, identidad del hospedante y concentración en la copa. Comparar con árboles vecinos.", "source": "https://ecologia.misiones.gob.ar/yerba-del-pajarito-una-planta-habitual-de-misiones-que-no-necesariamente-representa-una-plaga-para-los-arboles/"}}, {"plant": {"name": "Liga · Phoradendron", "latin": "Phoradendron liga", "type": "parasite", "family": "Viscaceae (SIB)", "icon": "🌿", "cycle": "Perenne", "source": "https://sib.gob.ar/especies/phoradendron-liga", "role": "Hemiparásita nativa · identificación técnica", "recognize": "Planta de vida parasítica sobre hospedantes leñosos. Para distinguirla de otras “ligas”, registrar hojas, tallos, estructuras reproductivas y unión al hospedante; solicitar identificación botánica.", "learn": "SENASA registra la especie como presente en Argentina. Ese registro nacional no diagnostica una plaga en una parcela ni establece la necesidad de control.", "distribution": "Kew incluye el noroeste y noreste argentino en su distribución nativa. SIB valida presencia en la Reserva Natural Formosa y diferencia otros registros aún sin validar.", "text": "La fotografía es un ejemplar de herbario de referencia, no una detección local. El nombre común “liga” también se aplica a Ligaria cuneifolia: usar el nombre científico.", "watch": "Medir abundancia y describir estado del hospedante antes de evaluar manejo. No extrapolar medidas de una especie parásita a otra.", "photo": {"image": "assets/Phoradendron_liga.jpg", "credit": "Instituto Nacional da Mata Atlântica (INMA) · Herbario MBML / Reflora", "license": "CC BY-SA 4.0", "source": "https://commons.wikimedia.org/wiki/File:LORANTHACEAE_phoradendron_liga_Eichler,_INMA_(MBML012986).pdf", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "species": "Phoradendron liga", "caption": "Fotografía digital de ejemplar seco de herbario MBML012986, Brasil (1999). Vista de la primera página del documento; no representa una planta viva ni síntomas de campo.", "herbarium": true}}, "health": {"symptoms": "Documentar presencia y unión con el hospedante. Amarillamiento o ramas secas pueden tener distintas causas y no confirman que esta planta sea responsable.", "parts": "Ramas del hospedante y estructuras completas de la planta parásita visibles desde el suelo.", "timing": "Registrar primera identificación, floración o fructificación observadas y evolución del hospedante entre visitas.", "pattern": "Diferenciar presencia confirmada por especialista de observación provisional; no marcar distribución regional a partir de un ejemplar.", "source": "https://sib.gob.ar/especies/phoradendron-liga"}}];
regionalPlants.forEach(({plant,health})=>{plantCatalog.push(plant);plantHealth[plant.name]=health});
plantCatalog.filter(p=>['Cuscuta','Jopo','Striga'].includes(p.name)).forEach(p=>p.type='reference');
const categoryNames={crop:'Cultivos',cover:'Coberturas',native:'Flora nativa y cactus',parasite:'Parásitas nativas',reference:'Parásitas: referencias generales'};
const comparedPlants=new Set();let catalogPage=0,catalogKey='';
function renderPlants(){document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('selected',b.dataset.category===$('plantFilter').value);b.setAttribute('aria-pressed',b.dataset.category===$('plantFilter').value)});const filter=$('plantFilter').value,query=normalize($('plantSearch').value),family=$('plantFamily').value,key=[filter,query,family].join('|');if(key!==catalogKey){catalogPage=0;catalogKey=key}const found=plantCatalog.filter(p=>(filter==='all'||p.type===filter)&&(family==='all'||p.family===family)&&normalize([p.name,p.latin,p.family,typeof translateText==='function'?translateText(p.name):''].join(' ')).includes(query)).sort((a,b)=>Object.keys(categoryNames).indexOf(a.type)-Object.keys(categoryNames).indexOf(b.type));const pages=Math.max(1,Math.ceil(found.length/6));catalogPage=Math.min(catalogPage,pages-1);$('plantCount').textContent=found.length+' de '+plantCatalog.length+' fichas';$('plantPage').textContent='Página '+(catalogPage+1)+' de '+pages;$('plantPrev').disabled=catalogPage===0;$('plantNext').disabled=catalogPage===pages-1;$('plantCards').innerHTML=found.slice(catalogPage*6,catalogPage*6+6).map((p,k,group)=>{const i=plantCatalog.indexOf(p);return `${k===0||group[k-1].type!==p.type?`<h3 class="catalog-group-title">${categoryNames[p.type]}</h3>`:''}<article class="plant-card compact-plant ${p.type}"><img loading="lazy" src="${p.photo.image.replace('assets/','assets/thumbs/').replace(/\.jpg$/,'.webp')}" alt="${escapeHTML(p.photo.species||p.latin)}"><div><span class="eyebrow">${p.role}</span><h3>${p.name}</h3><i translate="no">${p.latin}</i><p>${p.family} · ${p.cycle}</p>${p.photo.herbarium?'<span class="herbarium-tag">Ejemplar de herbario</span>':''}<div class="compact-actions"><button class="button open-plant" data-plant="${i}">Abrir ficha ↗</button><button class="secondary-button compare-plant" data-plant="${i}" aria-pressed="${comparedPlants.has(i)}" aria-label="Comparar ${p.name}">${comparedPlants.has(i)?'✓':'＋'}</button></div><small>Foto: <a href="${p.photo.source}" target="_blank" rel="noopener"><span translate="no">${escapeHTML(p.photo.credit)}</span></a> · <a href="${p.photo.licenseUrl}" target="_blank" rel="noopener">${escapeHTML(p.photo.license)}</a> · encuadre adaptado</small></div></article>`}).join('')||'<p>No hay coincidencias. Cambiá el nombre o los filtros.</p>';document.querySelectorAll('.open-plant').forEach(b=>b.onclick=()=>openPlant(Number(b.dataset.plant)));document.querySelectorAll('.compare-plant').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.plant);if(comparedPlants.has(i))comparedPlants.delete(i);else if(comparedPlants.size<2)comparedPlants.add(i);else{$('plantComparison').innerHTML='<p>Quitá una selección antes de agregar otra planta.</p>';document.querySelector('.comparison-fold').open=true;return}renderPlants();renderPlantComparison();document.querySelector('.comparison-fold').open=true})}
function openPlant(i){const p=plantCatalog[i],q=plantHealth[p.name],ph=p.photo;$('plantDetail').innerHTML=`<div class="detail-cover"><img src="${ph.image}" alt="Fotografía de ${escapeHTML(ph.species||p.latin)}"><div><span class="eyebrow">FICHA DE CAMPO · ${p.role}</span><h2 id="plantDialogTitle">${p.name}</h2><i translate="no">${p.latin}</i><p>${p.family} · ${p.cycle}</p></div></div><p class="photo-credit">Foto: <a href="${ph.source}" target="_blank" rel="noopener"><span translate="no">${escapeHTML(ph.credit)}</span></a> · <a href="${ph.licenseUrl}" target="_blank" rel="noopener">${escapeHTML(ph.license)}</a> · encuadre adaptado. ${ph.species?'Ejemplar representativo: '+ph.species+'.':''}</p>${ph.caption?`<p class="photo-caption">${ph.caption}</p>`:''}<div class="detail-tabs" role="tablist" aria-label="Contenido de la ficha"><button role="tab" id="tab-recognize" aria-selected="true" aria-controls="detail-recognize" data-detail="recognize">① Reconocer</button><button role="tab" id="tab-health" aria-selected="false" aria-controls="detail-health" data-detail="health">② Señales y síntomas</button><button role="tab" id="tab-record" aria-selected="false" aria-controls="detail-record" data-detail="record">③ Registrar</button></div><section id="detail-recognize" role="tabpanel" aria-labelledby="tab-recognize"><h3>Cómo reconocerla</h3><p>${p.recognize}</p><h3>Función y cuidado</h3><p>${p.learn}</p><p>${p.text}</p>${p.distribution?`<h3>Distribución documentada</h3><p>${p.distribution}</p>`:''}<p>${p.watch}</p><a href="${p.source}" target="_blank" rel="noopener">Fuente botánica ↗</a></section><section id="detail-health" role="tabpanel" aria-labelledby="tab-health" hidden><div class="health-note">Ejemplos para orientar la observación, no diagnóstico ni lista exhaustiva de enfermedades. La fotografía muestra la especie, no necesariamente los síntomas descritos.</div><h3>Qué señales buscar</h3><p>${q.symptoms}</p><div class="health-grid"><article><h4>Parte donde mirar</h4><p>${q.parts}</p></article><article><h4>Cuándo observar</h4><p>${q.timing}</p></article><article><h4>Distribución en el lote</h4><p>${q.pattern}</p></article><article><h4>Qué puede confundirse</h4><p>Falta o exceso de agua, nutrición, senescencia, daño mecánico y otras causas pueden parecerse. Compará con plantas sanas de igual variedad y etapa.</p></article></div><p>No se asignan meses de siembra ni fechas de aparición universales: cambian con la localidad de Jujuy, altitud, variedad y manejo.</p><a href="${q.source}" target="_blank" rel="noopener">Fuente de observación y sanidad ↗</a></section><section id="detail-record" role="tabpanel" aria-labelledby="tab-record" hidden><h3>Un registro que permita comparar visitas</h3><ol><li>Anotá fecha de visita y primera fecha en que viste el síntoma.</li><li>Identificá etapa, órgano afectado y distribución: aislada, focos, bordes, franjas o bajos.</li><li>Fotografiá una planta completa, el detalle y una planta sana comparable. Guardá las fotos con fecha y punto del lote.</li><li>Registrá lluvias, riego y labores previas; repetí la observación sobre el mismo punto.</li></ol><p>El cuaderno guarda texto y coordenadas en este navegador. Las fotos se conservan por separado. Una señal satelital no confirma la causa.</p><p><a href="https://content.ces.ncsu.edu/extension-gardener-handbook/7-diagnostics" target="_blank" rel="noopener">Método de observación: NC State Extension ↗</a></p><button id="recordThisPlant" class="button">Registrar observación de ${p.name} ↗</button></section>`;document.querySelectorAll('[data-detail]').forEach(b=>{b.onclick=()=>{document.querySelectorAll('[data-detail]').forEach(t=>{const on=t===b;t.setAttribute('aria-selected',on);t.tabIndex=on?0:-1;$('detail-'+t.dataset.detail).hidden=!on})};b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const ts=[...document.querySelectorAll('[data-detail]')],n=(ts.indexOf(b)+(e.key==='ArrowRight'?1:2))%3;ts[n].click();ts[n].focus()}}});$('recordThisPlant').onclick=()=>{$('plantDialog').close();$('observedPlant').value=p.name+' ('+p.latin+')';$('notebookFold').open=true;$('observationForm').scrollIntoView({behavior:'smooth'});$('observedDate').focus()};$('plantDialog').showModal();$('plantDialog').scrollTop=0;}
function renderPlantComparison(){const plants=[...comparedPlants].map(i=>plantCatalog[i]);$('plantComparison').innerHTML=plants.length===2?`<h3>Aprender comparando</h3><p>¿Comparten familia? Alternar plantas de la misma familia puede mantener problemas sanitarios comunes. Esta comparación no valida una rotación.</p><div class="comparison-scroll"><table><thead><tr><th>Característica</th>${plants.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${[['Nombre científico','latin'],['Familia','family'],['Ciclo','cycle'],['Reconocimiento','recognize'],['Función y cuidado','learn']].map(([name,key])=>`<tr><th>${name}</th>${plants.map(p=>`<td>${p[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<h3>Aprender comparando</h3><p>Seleccioná dos plantas para comparar familia, ciclo y rasgos. ${plants.length?'Primera selección: '+plants[0].name+'.':'¿En qué se parecen el tomate y la papa?'}</p>`}
