function nearestPublishedDate(ranges, requested){let best=null;for(const raw of ranges||[]){const parts=raw.split('/'),start=parts[0].slice(0,10),end=(parts[1]||parts[0]).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||requested<start)continue;const cap=requested<end?requested:end;let candidate=start;if(parts.length===1){candidate=start}else{const m=/^P(\d+)([DMY])$/.exec(parts[2]||'P1D');if(!m)continue;const n=Number(m[1]),a=new Date(start+'T00:00:00Z'),b=new Date(cap+'T00:00:00Z');if(m[2]==='D'){a.setUTCDate(a.getUTCDate()+Math.floor((b-a)/86400000/n)*n)}else if(m[2]==='M'){const steps=Math.floor(((b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth())/n);a.setUTCMonth(a.getUTCMonth()+steps*n);if(iso(a)>cap)a.setUTCMonth(a.getUTCMonth()-n)}else{a.setUTCFullYear(a.getUTCFullYear()+Math.floor((b.getUTCFullYear()-a.getUTCFullYear())/n)*n);if(iso(a)>cap)a.setUTCFullYear(a.getUTCFullYear()-n)}candidate=iso(a)}if(candidate<=requested&&(!best||candidate>best))best=candidate}return best}
