function applyAvailability(records){for(const cfg of Object.values(layerConfigs)){const p=records[cfg.id];if(!p)continue;cfg.latest=p.latest;layerAvailability[cfg.id]=p}}
function updateAvailabilityPanel(){if(!$('availabilityStatus'))return;const tr=(es,en)=>pageLanguage==='en'?en:es,cfg=currentLayer(),requested=$('mapDate').value,shown=imageDate(cfg,requested),latest=layerAvailability[cfg.id]?.latest||cfg.latest;const status=$('availabilityStatus');$('elevationModeLabel').hidden=state.layer!=='elevation';$('followLatestText').textContent=tr('Seguir la última fecha publicada','Follow latest published date');$('followLatest').checked=followLatest;$('followLatest').disabled=!!cfg.static;$('catalogueRefresh').textContent=cataloguePending?tr('Consultando NASA…','Querying NASA…'):tr('↻ Buscar novedades','↻ Check for updates');$('catalogueRefresh').disabled=cataloguePending;$('availableLatest').textContent=tr('Ir al último dato disponible','Go to latest available data');$('availableLatest').hidden=!!cfg.static||!latest;
if(cfg.static){status.textContent=state.layer==='elevation'?(cfg.id==='ASTER_GDEM_Color_Index'?tr('ASTER · referencia de altitud entre 83° S y 83° N. Los extremos polares quedan fuera de cobertura.','ASTER · reference elevation between 83° S and 83° N. The polar extremes are outside coverage.'):tr('SRTM · referencia de altitud entre 56° S y 60° N. Elegí ASTER para altas latitudes.','SRTM · reference elevation between 56° S and 60° N. Choose ASTER for high latitudes.')):tr('Imagen de referencia: no es una medición diaria.','Reference imagery: not a daily measurement.')}else if(!shown){status.textContent=tr('No hay una fecha publicada anterior o igual a ','No published date on or before ')+requested+tr('. Elegí el último dato disponible.','. Choose the latest available data.')}else{const unit=cfg.monthly?tr('Mes mostrado: ','Month shown: '):cfg.annual?tr('Año mostrado: ','Year shown: '):tr('Imagen mostrada: ','Image shown: ');status.textContent=tr('Fecha solicitada: ','Requested date: ')+requested+' · '+unit+shown+(shown!==requested?(cfg.monthly||cfg.annual||cfg.periodDays?tr(' · Período publicado anterior o que contiene la fecha.',' · Published period preceding or containing the date.'):tr(' · NASA no publica imagen para el día solicitado; se muestra la anterior disponible, sin rellenar datos.',' · NASA has no image for the requested day; the previous available image is shown, without filling data.')):'')+(latest?tr(' · Disponible hasta ',' · Available through ')+latest:'')}
status.classList.toggle('date-gap',!cfg.static&&shown!==requested);$('catalogueStatus').textContent=(catalogueChecked?tr('Catálogo verificado: ','Catalogue checked: ')+new Date(catalogueChecked).toLocaleString(pageLanguage==='en'?'en-GB':'es-AR',{timeZone:'America/Argentina/Jujuy',hourCycle:'h23'})+' (Argentina)':tr('Catálogo de respaldo verificado el 14/11/2026.','Backup catalogue verified on 14 November 2026.'))+' · '+(catalogueError?tr('No se pudo actualizar; se conserva la última disponibilidad conocida.','Update unavailable; retaining last known availability.'):tr('Revisión automática al abrir, cada hora y al volver a la página. Cada producto tiene su propio ritmo de publicación.','Automatic checks on opening, hourly and when returning to the page. Each product has its own publication schedule.'));}
async function refreshLayerCatalogue(){if(cataloguePending)return;cataloguePending=true;updateAvailabilityPanel();try{const response=await fetch('https://gibs.earthdata.nasa.gov/wmts/epsg4326/best/1.0.0/WMTSCapabilities.xml',{cache:'no-cache',signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error('NASA HTTP '+response.status);const doc=new DOMParser().parseFromString(await response.text(),'text/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('Invalid catalogue');const records={};for(const layer of doc.getElementsByTagNameNS('*','Layer')){const id=layer.getElementsByTagNameNS('*','Identifier')[0]?.textContent;if(!Object.values(layerConfigs).some(c=>!c.static&&c.id===id))continue;const dimension=[...layer.getElementsByTagNameNS('*','Dimension')].find(d=>d.getElementsByTagNameNS('*','Identifier')[0]?.textContent==='Time');if(!dimension)continue;const ranges=[...dimension.getElementsByTagNameNS('*','Value')].map(v=>v.textContent.trim());const latest=(dimension.getElementsByTagNameNS('*','Default')[0]?.textContent||'').slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(latest)&&ranges.length)records[id]={latest,ranges}}if(!Object.keys(records).length)throw Error('Empty catalogue');applyAvailability(records);catalogueChecked=new Date().toISOString();catalogueError=false;try{localStorage.setItem('terrajujuy-catalogue-v1',JSON.stringify({checked:catalogueChecked,records:layerAvailability}))}catch{}if(followLatest&&!currentLayer().static)$('mapDate').value=currentLayer().latest||iso(ago(7));if(!historyTimer&&!windTimer)renderMap()}catch(e){catalogueError=true}finally{cataloguePending=false;updateAvailabilityPanel()}}
function automaticRefresh(){if(document.hidden)return;const day=iso(new Date());$('mapDate').max=day;$('compareDate').max=day;refreshLayerCatalogue();if(!historyMode&&!windTimer&&!$('refresh').disabled){lastRefreshDay=day;loadData();if(followLatest&&!currentLayer().static)$('mapDate').value=currentLayer().latest||iso(ago(7));renderMap()}}

$('followLatest').onchange=()=>{followLatest=$('followLatest').checked;if(followLatest){pauseHistory();pauseWind();historyMode=false;if(!currentLayer().static)$('mapDate').value=currentLayer().latest||iso(ago(7))}renderMap()};$('availableLatest').onclick=()=>{followLatest=true;pauseHistory();pauseWind();historyMode=false;$('mapDate').value=currentLayer().latest||iso(ago(7));renderMap()};$('catalogueRefresh').onclick=()=>refreshLayerCatalogue();$('elevationMode').onchange=renderMap;
initializeFieldTools();showSection(location.hash.slice(1)||"monitor",false);renderMap();rotations();applyHistory();loadData();refreshLayerCatalogue();setInterval(automaticRefresh,3600000);



