// Protected scientific names and places remain unchanged even inside longer text.
const protectedSet=new Set(protectedWords);
translationPattern=new RegExp([...new Set([...protectedWords,...Object.keys(englishDictionary)])].sort((a,b)=>b.length-a.length).map(escapeRegex).join('|'),'gu');
function translateText(text){
 if(!translationPattern)return text;
 const trimmed=text.trim();if(Object.prototype.hasOwnProperty.call(englishDictionary,trimmed))return text.replace(trimmed,englishDictionary[trimmed]);
 return text.replace(translationPattern,(match,offset,whole)=>{
  if(protectedSet.has(match))return match;
  const before=whole[offset-1]||'',after=whole[offset+match.length]||'';
  if((/^\p{L}/u.test(match)&&/\p{L}/u.test(before))||(/\p{L}$/u.test(match)&&/\p{L}/u.test(after)))return match;
  return englishDictionary[match]??match;
 });
}
